/**
 * Unit tests for DateTimeZone#getOffsetFromLocal.
 * Since DateTimeZone is an abstract class and many methods are abstract,
 * we use a Spy on a subclass or a Mockito spy to control the behavior 
 * of the abstract methods getOffset and nextTransition.
 */
public class DateTimeZone_getOffsetFromLocal_TriageGen1Test {

    /**
     * Test Case 1: offsetLocal == offsetAdjusted
     * Covers the path where the first estimate is correct and no DST boundary logic is triggered.
     */
    @Test
    public void testGetOffsetFromLocal_OffsetsAreSame() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(1));
        long instantLocal = 1000L;

        // Mock getOffset to return the same value regardless of input to simulate no change
        when(zone.getOffset(anyLong())).thenReturn(3600);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(3600, result);
    }

    /**
     * Test Case 2: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) >= 0
     * Covers the branch where offsets differ (DST boundary) but the difference is positive (e.g., moving from DST to Standard).
     */
    @Test
    public void testGetOffsetFromLocal_OffsetsDifferPositiveDiff() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(1));
        long instantLocal = 1000L;
        int offsetLocal = 3600;
        int offsetAdjusted = 1800; // offsetLocal - offsetAdjusted = 1800 (>= 0)

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        // instantAdjusted = 1000 - 3600 = -2600
        when(zone.getOffset(-2600L)).thenReturn(offsetAdjusted);

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetAdjusted, result);
    }

    /**
     * Test Case 3: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) < 0 
     * AND nextLocal == nextAdjusted
     * Covers the branch where the difference is negative, but the transition check prevents returning offsetAdjusted.
     */
    @Test
    public void testGetOffsetFromLocal_NegativeDiff_NextTransitionSame() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(1));
        long instantLocal = 1000L;
        int offsetLocal = 1800;
        int offsetAdjusted = 3600; // offsetLocal - offsetAdjusted = -1800 (< 0)

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        // instantAdjusted = 1000 - 1800 = -800
        when(zone.getOffset(-800L)).thenReturn(offsetAdjusted);

        // To satisfy the if (nextLocal != nextAdjusted) condition being false (so it returns offsetAdjusted)
        // Actually, the logic says: if (nextLocal != nextAdjusted) return offsetLocal; 
        // else return offsetAdjusted;
        // We want to test the 'else' part here to return offsetAdjusted
        when(zone.nextTransition(-800L)).thenReturn(5000L);
        when(zone.nextTransition(1000L - 3600L)).thenReturn(5000L); // instantLocal - offsetAdjusted = 1000 - 3600 = -2600

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetAdjusted, result);
    }

    /**
     * Test Case 4: offsetLocal != offsetAdjusted AND (offsetLocal - offsetAdjusted) < 0 
     * AND nextLocal != nextAdjusted
     * Covers the branch where the negative difference triggers the "push back" protection, returning offsetLocal.
     */
    @Test
    public void testGetOffsetFromLocal_NegativeDiff_NextTransitionDifferent() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(1));
        long instantLocal = 1000L;
        int offsetLocal = 1800;
        int offsetAdjusted = 3600; // offsetLocal - offsetAdjusted = -1800 (< 0)

        when(zone.getOffset(instantLocal)).thenReturn(offsetLocal);
        // instantAdjusted = 1000 - 1800 = -800
        when(zone.getOffset(-800L)).thenReturn(offsetAdjusted);

        // Force nextLocal != nextAdjusted
        when(zone.nextTransition(-800L)).thenReturn(5000L);
        when(zone.nextTransition(1000L - 3600L)).thenReturn(6000L); // -2600

        int result = zone.getOffsetFromLocal(instantLocal);
        assertEquals(offsetLocal, result);
    }
}
